#include <stdio.h>

typedef enum { STATE_MENU, STATE_PLAYING, STATE_GAMEOVER, STATE_COUNT } GameState;
typedef GameState (*UpdateFn)(int frame);

GameState update_menu(int frame) {
    printf("%d: menu\n", frame);
    return STATE_PLAYING;
}
GameState update_playing(int frame) {
    printf("%d: playing\n", frame);
    return frame < 2 ? STATE_PLAYING : STATE_GAMEOVER;
}
int main(void) {
    UpdateFn updates[STATE_COUNT] = { update_menu, update_playing, NULL };
    GameState state = STATE_MENU;
    for (int frame = 0; updates[state] != NULL; frame++) {
        state = updates[state](frame);
    }
    printf("game over\n");
    return 0;
}

